/// A completed solve: the plain result fields plus ownership of the
/// full Rust result behind them. report()/pretty_report() render the
/// Rust-side text (status, cost, the timing breakdown and the
/// backend's plan when gathered); plan() returns the sparse backend's
/// SchurPlan as data, steps() the per-attempt timeline. Copies share
/// ownership of the Rust result.
class LmResult : public LmResultT<double> {
public:
    LmResult() : LmResultT<double>() {}
    explicit LmResult(const LmResultT<double>& raw) : LmResultT<double>(raw) {
        if (detail)
            guard_ = std::shared_ptr<void>(detail, ffi::graph_result_free);
    }
    /// Text report; the pointer is valid until the next report call
    /// on this result or the destruction of its last copy.
    const char* report() const {
        return detail ? ffi::graph_result_report(detail, false) : "";
    }
    /// report() with colour and box-drawing glyphs.
    const char* pretty_report() const {
        return detail ? ffi::graph_result_report(detail, true) : "";
    }
    /// The sparse backend's plan; empty for dense and band solves.
    option<SchurPlan> plan() const {
        SchurPlan p;
        if (detail && ffi::graph_result_plan(detail, &p))
            return p;
        return {};
    }
    /// The per-attempt timeline (Rust's LmTiming::steps); empty
    /// unless the solve ran with gather_timing.
    std::vector<LmStep> steps() const {
        std::vector<LmStep> out;
        if (!detail)
            return out;
        out.resize(ffi::graph_result_steps(detail, nullptr, 0));
        if (!out.empty())
            ffi::graph_result_steps(detail, out.data(), out.size());
        return out;
    }

private:
    std::shared_ptr<void> guard_;
};

